function update(dt) {
  if (phase !== 'playing') return;
  // Player movement based on arrow keys or WASD
  let ax = 0, ay = 0;
  if (keys.has('ArrowLeft') || keys.has('a') || keys.has('A')) ax -= 1;
  if (keys.has('ArrowRight') || keys.has('d') || keys.has('D')) ax += 1;
  if (keys.has('ArrowUp') || keys.has('w') || keys.has('W')) ay -= 1;
  if (keys.has('ArrowDown') || keys.has('s') || keys.has('S')) ay += 1;
  // normalize diagonal
  if (ax !== 0 && ay !== 0) { const norm = Math.hypot(ax, ay); ax /= norm; ay /= norm; }
  // apply acceleration
  player.vx += ax * PLAYER_ACC * dt;
  player.vy += ay * PLAYER_ACC * dt;
  // apply friction
  const speed = Math.hypot(player.vx, player.vy);
  if (speed > 0) {
    const dec = PLAYER_FRICTION * dt;
    if (dec >= speed) { player.vx = 0; player.vy = 0; } else { player.vx *= (1 - dec / speed); player.vy *= (1 - dec / speed); }
  }
  // clamp max speed
  const curSpeed = Math.hypot(player.vx, player.vy);
  if (curSpeed > PLAYER_MAX_SPEED) { const factor = PLAYER_MAX_SPEED / curSpeed; player.vx *= factor; player.vy *= factor; }
  // update position
  player.x += player.vx * dt;
  player.y += player.vy * dt;
  // keep within canvas bounds
  player.x = Math.min(Math.max(player.x, 0), canvas.width);
  player.y = Math.min(Math.max(player.y, 0), canvas.height);

  // Hazard spawning
  hazardTimer += dt;
  if (hazardTimer >= HAZARD_SPAWN_INTERVAL) {
    hazardTimer -= HAZARD_SPAWN_INTERVAL;
    // spawn at random edge
    const side = Math.floor(Math.random()*4);
    let hx, hy, hvx = 0, hvy = 0;
    if (side===0) { hx=0; hy=Math.random()*canvas.height; hvx=HAZARD_SPEED; }
    else if (side===1) { hx=canvas.width; hy=Math.random()*canvas.height; hvx=-HAZARD_SPEED; }
    else if (side===2) { hx=Math.random()*canvas.width; hy=0; hvy=HAZARD_SPEED; }
    else { hx=Math.random()*canvas.width; hy=canvas.height; hvy=-HAZARD_SPEED; }
    // avoid safe radius around player start (400,300)
    const dx = hx-400, dy = hy-300;
    if (Math.hypot(dx, dy) < SAFE_RADIUS) {
      // shift outward
      const angle = Math.atan2(dy, dx);
      hx = 400 + Math.cos(angle)*(SAFE_RADIUS+5);
      hy = 300 + Math.sin(angle)*(SAFE_RADIUS+5);
    }
    hazards.push({ x:hx, y:hy, vx:hvx, vy:hvy, radius:12, alive:true });
  }

  // Update hazards
  for (const h of hazards) {
    if (!h.alive) continue;
    h.x += h.vx * dt;
    h.y += h.vy * dt;
    // offscreen removal
    if (h.x < -50 || h.x > canvas.width+50 || h.y < -50 || h.y > canvas.height+50) h.alive = false;
    // collision with player
    const dx = h.x - player.x;
    const dy = h.y - player.y;
    if (Math.hypot(dx, dy) < h.radius + 8) {
      phase = 'gameover';
      h.alive = false;
    }
  }
}

